corrected_code:
const express = require('express');
const router = express.Router();
const { DeviceToken } = require('../models');

router.delete('/api/notifications/apns/:deviceToken', authenticateUser, async (req, res) => {
  const { deviceToken } = req.params;

  const deleted = await DeviceToken.destroy({
    where: { token: deviceToken, provider: 'APNS', userId: req.user.id }
  });

  if (!deleted) {
    return res.status(403).json({ error: 'Token not found or unauthorized' });
  }

  return res.json({ success: true, token: deviceToken });
});
